import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) {
        Set<String> stops = new TreeSet<>();
        stops.add("Recto");
        stops.add("Monumento");
        stops.add("Divisoria");
        for (String stop : stops) {
            System.out.println("Stop: " + stop);
        }

        Map<String, Integer> trips = new TreeMap<>();
        trips.put("Mang Ramon", 5);
        trips.put("Kuya Ben", 9);
        trips.put("Aling Rosa", 3);

        for (String driver : trips.keySet()) {
            System.out.print(driver + " ");          // keys
        }
        System.out.println();
        int total = 0;
        for (int count : trips.values()) {           // values
            total = total + count;
        }
        System.out.println("Total trips: " + total);
        for (Map.Entry<String, Integer> e
                : trips.entrySet()) {                // both
            System.out.println(e.getKey() + " -> "
                + e.getValue());
        }
    }
}

