import java.io.File;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        File folder = new File("records");             // a folder is also a File
        System.out.println("Folder made? " + folder.mkdir());
        System.out.println("Is a folder? " + folder.isDirectory());

        File trips = new File(folder, "trips.txt");    // records/trips.txt
        File old = new File(folder, "old_log.txt");    // records/old_log.txt
        try {
            trips.createNewFile();
            old.createNewFile();
        } catch (IOException e) {
            System.out.println("Could not create: " + e.getMessage());
        }

        String[] names = folder.list();                // names inside the folder
        Arrays.sort(names);                            // list() promises no order
        System.out.println("Inside records: " + Arrays.toString(names));

        System.out.println("Delete old_log.txt? " + old.delete());
        System.out.println("Delete it again? " + old.delete());
        System.out.println("Delete the folder? " + folder.delete());
        System.out.println("Left inside: " + Arrays.toString(folder.list()));
    }
}

