import java.io.FileReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) {
        String firstLine = "";
        int commas = 0;
        boolean firstDone = false;
        try (FileReader reader = new FileReader("fleet.txt")) {  // closes by itself
            int ch = reader.read();          // ONE character, given as a number
            while (ch != -1) {               // -1 means "end of file"
                if (ch == '\n') {
                    firstDone = true;        // the first line has ended
                } else if (ch == ',') {
                    commas++;
                }
                if (!firstDone && ch != '\r') {
                    firstLine = firstLine + (char) ch;   // number back to a letter
                }
                ch = reader.read();
            }
        } catch (IOException e) {
            System.out.println("Cannot read: " + e.getMessage());
        }
        System.out.println("First line: " + firstLine);
        System.out.println("Commas in the file: " + commas);
    }
}

