import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class Main {
    // turns ONE line of text into a Vehicle object
    static Vehicle toVehicle(String line) {
        String[] part = line.split(",");   // "Bus,BUS 789,Aling Rosa,50" -> 4 parts
        if (part[0].equals("Jeepney")) {
            return new Jeepney(part[1], part[2], part[3]);
        } else if (part[0].equals("Tricycle")) {
            return new Tricycle(part[1], part[2], part[3]);
        } else {
            return new Bus(part[1], part[2], Integer.parseInt(part[3]));
        }
    }

    public static void main(String[] args) {
        List<Vehicle> fleet = new ArrayList<>();
        try (BufferedReader in = new BufferedReader(new FileReader("fleet.txt"))) {
            String line = in.readLine();       // a whole line, or null at the end
            while (line != null) {
                if (!line.trim().isEmpty()) {  // skip blank lines
                    fleet.add(toVehicle(line));
                }
                line = in.readLine();
            }
        } catch (IOException e) {
            System.out.println("Cannot read: " + e.getMessage());
        }
        System.out.println("Loaded " + fleet.size() + " vehicles from fleet.txt");
        for (Vehicle v : fleet) {
            v.showInfo();
        }
    }
}

