import java.io.File;
import java.io.FileNotFoundException;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        double total = 0;
        int count = 0;
        try (Scanner sc = new Scanner(new File("fares.txt"))) {  // a FILE, not System.in
            while (sc.hasNextDouble()) {          // is the next word a number?
                total = total + sc.nextDouble();
                count++;
            }
        } catch (FileNotFoundException e) {
            System.out.println("Missing file: " + e.getMessage());
        }
        System.out.println("Fares read: " + count);
        System.out.println("Total collected: P" + total);
        if (count > 0) {
            System.out.printf("Average fare: P%.2f%n", total / count);
        }
    }
}

