import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.io.Reader;
import java.io.StringReader;

public class Main {
    // works with ANY Reader: a real file, or a String acting like a file
    static int countVehicles(Reader source) throws IOException {
        BufferedReader in = new BufferedReader(source);
        int count = 0;
        String line = in.readLine();
        while (line != null) {
            if (!line.trim().isEmpty()) {
                count++;
            }
            line = in.readLine();
        }
        in.close();
        return count;
    }

    public static void main(String[] args) {
        String sample = "Jeepney,NXA 123,Mang Ramon,Monumento-Divisoria\n"
