import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class Main {
    static Vehicle toVehicle(String line) {           // same as Step 4
        String[] part = line.split(",");
        if (part[0].equals("Jeepney")) {
            return new Jeepney(part[1], part[2], part[3]);
        } else if (part[0].equals("Tricycle")) {
            return new Tricycle(part[1], part[2], part[3]);
        } else {
            return new Bus(part[1], part[2], Integer.parseInt(part[3]));
        }
    }

    // the REVERSE of toVehicle: one Vehicle back into one line of text
    static String toLine(Vehicle v) {
        String middle = "," + v.getPlateNumber() + "," + v.getDriverName() + ",";
        if (v instanceof Jeepney) {
            return "Jeepney" + middle + ((Jeepney) v).getRoute();
        } else if (v instanceof Tricycle) {
            return "Tricycle" + middle + ((Tricycle) v).getToda();
        } else {
            return "Bus" + middle + ((Bus) v).getSeats();
        }
    }

    static List<Vehicle> load(String fileName) {
        List<Vehicle> fleet = new ArrayList<>();
        try (BufferedReader in = new BufferedReader(new FileReader(fileName))) {
            String line = in.readLine();
            while (line != null) {
                if (!line.trim().isEmpty()) {
                    fleet.add(toVehicle(line));
                }
                line = in.readLine();
            }
        } catch (IOException e) {
            System.out.println("Cannot read " + fileName + ": " + e.getMessage());
        }
        return fleet;
    }

    public static void main(String[] args) {
        List<Vehicle> fleet = load("fleet.txt");
        System.out.println("Loaded from fleet.txt: " + fleet.size());
        fleet.add(new Tricycle("TRC 654", "Mang Lito", "Bagong Silang TODA"));

        String backup = "fleet_backup.txt";
        try (BufferedWriter out = new BufferedWriter(new FileWriter(backup))) {
            for (Vehicle v : fleet) {
                out.write(toLine(v));
                out.newLine();           // ends the line
            }
        } catch (IOException e) {
            System.out.println("Cannot write: " + e.getMessage());
        }
        System.out.println("Saved to " + backup + ": " + fleet.size());

        List<Vehicle> again = load(backup);
        System.out.println("Reloaded: " + again.size());
        again.get(again.size() - 1).showInfo();
    }
}

