import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.util.Map;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        Map<String, Integer> stock = new TreeMap<>();
        String file = "stock.txt";
        try (BufferedReader in = new BufferedReader(new FileReader(file))) {
            String line = in.readLine();
            while (line != null) {
                String[] p = line.split(",");
                try {
                    stock.put(p[0], Integer.parseInt(p[1]));
                } catch (NumberFormatException e) {
                    System.out.println("Skipped bad line: " + line);
                }
                line = in.readLine();
            }
        } catch (IOException e) {
            System.out.println("No stock yet: " + e.getMessage());
        }
        // Ana buys 2 Bread
        stock.put("Bread", stock.getOrDefault("Bread", 0) - 2);
        // APPEND: the sales log keeps every old line
        try (FileWriter log = new FileWriter("sales_log.txt", true)) {
            log.write("Ana bought 2 Bread\n");
        } catch (IOException e) {
            System.out.println("Log failed: " + e.getMessage());
        }
        // OVERWRITE: stock.txt always holds today's numbers
        try (BufferedWriter out = new BufferedWriter(new FileWriter(file))) {
            for (Map.Entry<String, Integer> e : stock.entrySet()) {
                out.write(e.getKey() + "," + e.getValue());
                out.newLine();
            }
        } catch (IOException e) {
            System.out.println("Save failed: " + e.getMessage());
        }
        System.out.println("Stock saved: " + stock);
    }
}

